const body = $json.body || {};
if (!body.systemPrompt || !body.userPrompt) throw new Error('Missing search prompt');
return items;

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content;
if (typeof content !== 'string' || !content.trim()) throw new Error('DeepSeek returned no JSON content');
const cleaned = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const parsed = JSON.parse(cleaned);
const matches = Array.isArray(parsed.matches) ? parsed.matches.slice(0, 12).map(m => ({ shiftId: Number(m.shiftId), reason: String(m.reason || '').trim() })) : [];
return [{ json: {
  interpretation: String(parsed.interpretation || '').trim(),
  matches,
  source: 'N8N_DEEPSEEK'
} }];
